'use strict';
const $=id=>document.getElementById(id),db=supabase.createClient(HUB_CONFIG.url,HUB_CONFIG.key),categories=['공지사항','업무공유','안전·품질','질문과 답변','자유게시판'];
let posts=[],metrics=[],commentCounts={},user=null,profile=null,authMode='login',editId=null,activePost=null,search='',page=1,site='전체 사업장',days=7,loading=false,routeTicket=0;
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>new Date(s).toLocaleDateString('ko-KR',{month:'2-digit',day:'2-digit'}),fullDate=s=>new Date(s).toLocaleString('ko-KR',{year:'numeric',month:'long',day:'numeric',hour:'2-digit',minute:'2-digit'});
const toast=(s)=>{$('toast').textContent=s;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,4500)};
const tag=c=>`<span class="tag ${c==='공지사항'?'notice':c==='안전·품질'?'quality':c==='질문과 답변'?'question':''}">${escapeHTML(c)}</span>`;
const sampleBanner='<div class="sample-banner"><b>SAMPLE DATA</b><span>교육용 가상 게시글과 업무 지표입니다. 실제 두산밥캣의 운영 실적이 아닙니다.</span></div>';
function errorMessage(e){const s=e?.message||String(e);if(/Invalid login credentials/i.test(s))return '이메일 또는 비밀번호를 확인해 주세요.';if(/Email not confirmed/i.test(s))return '기존 가입이 미완료 상태입니다. 회원가입에서 같은 이메일로 다시 가입해 주세요.';if(/email.*not.*authoriz|Error sending confirmation email/i.test(s))return '현재 인증 메일 발송이 제한되어 있습니다. 운영자의 메일 발송 설정이 필요합니다.';if(/already registered/i.test(s))return '이미 가입된 이메일입니다. 로그인해 주세요.';if(/rate limit|too many/i.test(s))return '요청이 많습니다. 잠시 후 다시 시도해 주세요.';if(/row-level security|permission denied/i.test(s))return '이 작업에 대한 권한이 없습니다. 로그인 상태를 확인해 주세요.';return s;}
function updateAuth(){$('authArea').innerHTML=user?`<div class="user-chip"><span class="avatar">${escapeHTML((profile?.display_name||user.user_metadata?.display_name||'멤버')[0])}</span><span>${escapeHTML(profile?.display_name||user.user_metadata?.display_name||'멤버')} 님</span><button class="link-btn" id="logout">로그아웃</button></div>`:'<div class="auth-buttons"><button class="secondary" id="login">로그인</button><button class="primary" id="signup">회원가입</button></div>';if(user)$('logout').onclick=async()=>{await db.auth.signOut();user=null;profile=null;await refresh();toast('로그아웃했습니다.')};else{$('login').onclick=()=>openAuth('login');$('signup').onclick=()=>openAuth('signup')}}
function openAuth(mode){authMode=mode;document.querySelectorAll('[data-auth]').forEach(b=>b.classList.toggle('active',b.dataset.auth===mode));document.querySelector('.signup-only').hidden=mode!=='signup';$('signupName').required=mode==='signup';$('authTitle').textContent=mode==='signup'?'함께 일할 준비가 되었나요?':'다시 만나 반갑습니다.';$('authSubmit').textContent=mode==='signup'?'회원가입':'로그인';$('password').autocomplete=mode==='signup'?'new-password':'current-password';$('authError').textContent='';if(!$('authDialog').open)$('authDialog').showModal();}
async function ensureProfile(){profile=null;if(!user)return;const {data,error}=await db.from('hub_profiles').select('*').eq('id',user.id).maybeSingle();if(error)throw error;if(data)profile=data;else{const row={id:user.id,display_name:String(user.user_metadata?.display_name||'새 멤버').slice(0,40),department:user.user_metadata?.department||'기타'};const r=await db.from('hub_profiles').upsert(row).select().single();if(r.error)throw r.error;profile=r.data;}updateAuth();}
$('authForm').onsubmit=async e=>{e.preventDefault();$('authSubmit').disabled=true;$('authError').textContent='';try{const email=$('email').value.trim(),password=$('password').value;if(authMode==='signup'){const display_name=$('signupName').value.trim();if(!display_name)throw Error('이름을 입력해 주세요.');const {data,error}=await db.auth.signUp({email,password,options:{data:{display_name,department:$('signupDepartment').value},emailRedirectTo:location.origin+location.pathname}});if(error)throw error;if(data.session){user=data.user;await ensureProfile();$('authDialog').close();await refresh();toast('가입이 완료되었습니다. 첫 글을 작성해 보세요.')}else{$('authError').style.color='#4c8a75';$('authError').textContent='가입 확인 이메일을 보냈습니다. 이메일의 확인 링크를 누른 후 로그인해 주세요.';}}else{const {data,error}=await db.auth.signInWithPassword({email,password});if(error)throw error;user=data.user;await ensureProfile();$('authDialog').close();await refresh();toast('로그인했습니다.');}$('password').value='';}catch(err){$('authError').style.color='';$('authError').textContent=errorMessage(err);}finally{$('authSubmit').disabled=false}};
for(const b of document.querySelectorAll('[data-auth]'))b.onclick=()=>openAuth(b.dataset.auth);document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
function openWrite(p=null){if(!user){openAuth('login');toast('로그인 후 글을 작성할 수 있습니다.');return}editId=p?.id||null;$('writeTitle').textContent=p?'글 수정':'새 글 작성';$('postTitle').value=p?.title||'';$('postBody').value=p?.body||'';$('postCategory').value=p?.category||'업무공유';$('postDepartment').value=p?.department||'전사';$('postSubmit').textContent=p?'수정 저장':'게시하기';$('writeError').textContent='';$('writeDialog').showModal();}
$('writeForm').onsubmit=async e=>{e.preventDefault();$('postSubmit').disabled=true;try{const row={title:$('postTitle').value.trim(),body:$('postBody').value.trim(),category:$('postCategory').value,department:$('postDepartment').value};if(!row.title||!row.body)throw Error('제목과 내용을 입력해 주세요.');const q=editId?db.from('hub_posts').update(row).eq('id',editId):db.from('hub_posts').insert({...row,author_id:user.id});const {data,error}=await q.select('id').single();if(error)throw error;$('writeDialog').close();await loadData();location.hash='post/'+data.id;await renderRoute();toast(editId?'글을 수정했습니다.':'새 글을 게시했습니다.');}catch(err){$('writeError').textContent=errorMessage(err)}finally{$('postSubmit').disabled=false}};
$('confirmDelete').onclick=async()=>{if(!activePost||activePost.author_id!==user?.id)return;$('confirmDelete').disabled=true;try{const {error}=await db.from('hub_posts').delete().eq('id',activePost.id);if(error)throw error;$('deleteDialog').close();await loadData();location.hash='board';await renderRoute();toast('글을 삭제했습니다.')}catch(e){toast(errorMessage(e))}finally{$('confirmDelete').disabled=false}};
async function loadData(){const results=await Promise.all([db.from('hub_posts').select('*').order('created_at',{ascending:false}).limit(1000),db.from('hub_metrics').select('*').order('metric_date',{ascending:true}),db.from('hub_comments').select('post_id')]);for(const r of results)if(r.error)throw r.error;posts=results[0].data;metrics=results[1].data;commentCounts={};results[2].data.forEach(c=>commentCounts[c.post_id]=(commentCounts[c.post_id]||0)+1);$('navCount').textContent=posts.length;$('connection').textContent='Supabase 연결됨';}
async function refresh(){if(loading)return;loading=true;$('refresh').disabled=true;try{await loadData();updateAuth();await renderRoute();}catch(e){$('connection').textContent='연결 확인 필요';$('main').innerHTML=`<div class="error-card"><h2>데이터를 불러오지 못했습니다.</h2><p>${escapeHTML(errorMessage(e))}</p><button class="secondary" onclick="location.reload()">다시 불러오기</button></div>`}finally{loading=false;$('refresh').disabled=false}}$('refresh').onclick=refresh;
function row(p){return `<div class="list-row" data-post="${p.id}" tabindex="0" role="link">${tag(p.category)}<div class="item-content"><strong>${escapeHTML(p.title)}</strong><small>${escapeHTML(p.author_name)} · ${escapeHTML(p.department)}${commentCounts[p.id]?' · 댓글 '+commentCounts[p.id]:''}</small></div><time>${date(p.created_at)}</time></div>`}
function bindPostLinks(){document.querySelectorAll('[data-post]').forEach(el=>{el.onclick=()=>location.hash='post/'+el.dataset.post;el.onkeydown=e=>{if(e.key==='Enter')el.click()}});document.querySelectorAll('[data-write]').forEach(b=>b.onclick=()=>openWrite());}
function renderDashboard(){const dates=[...new Set(metrics.map(m=>m.metric_date))].sort().slice(-days),selected=metrics.filter(m=>dates.includes(m.metric_date)&&(site==='전체 사업장'||m.site===site));const sums=selected.reduce((a,m)=>({production:a.production+m.production,target:a.target+m.target,quality:a.quality+Number(m.quality_rate)*m.production,checks:a.checks+m.safety_checks,safetyTarget:a.safetyTarget+m.safety_target}),{production:0,target:0,quality:0,checks:0,safetyTarget:0});const achievement=sums.target?sums.production/sums.target*100:0,quality=sums.production?sums.quality/sums.production:0,safety=sums.safetyTarget?sums.checks/sums.safetyTarget*100:0;const recent=posts.slice(0,5),notices=posts.filter(p=>p.category==='공지사항').slice(0,3),daily=dates.map(d=>{const rows=selected.filter(m=>m.metric_date===d);return {date:d,p:rows.reduce((n,m)=>n+m.production,0),t:rows.reduce((n,m)=>n+m.target,0)}}),max=Math.max(1,...daily.map(x=>Math.max(x.p,x.t)))*1.12;
$('main').innerHTML=`<div class="page-heading"><div><span class="eyebrow">OVERVIEW</span><h1>함께 만드는 더 나은 내일</h1><p>${user?escapeHTML(profile?.display_name||'멤버')+' 님, 오늘도 반갑습니다.':'팀의 소식과 업무 현황을 한눈에 확인하세요.'}</p></div><button class="primary" data-write>＋ 새 글 작성</button></div>${sampleBanner}<section class="hero"><div><span class="eyebrow">CONNECT. SHARE. GROW.</span><h2>우리의 경험이, 모두의 경쟁력이 됩니다.</h2><p>현장의 노하우부터 새로운 아이디어까지, 함께 나누는 워크스페이스</p></div><button class="primary" id="goBoard">게시판 둘러보기 ↗</button></section><div class="filter-line"><div><h2 style="font-size:14px">업무 현황</h2><span class="data-tag">● 가상 운영 데이터</span></div><div><select id="siteFilter" aria-label="사업장"><option>전체 사업장</option><option>인천</option><option>창원</option></select><select id="periodFilter" aria-label="집계 기간"><option value="7">최근 7일</option><option value="14">최근 14일</option></select></div></div><div class="kpis"><div class="kpi"><div class="label">생산 실적 <span class="icon">▥</span></div><strong>${sums.production.toLocaleString()}<em>대</em></strong><small><b>집계 ${dates.length}일</b> 목표 ${sums.target.toLocaleString()}대</small></div><div class="kpi"><div class="label">계획 달성률 <span class="icon">◎</span></div><strong>${achievement.toFixed(1)}<em>%</em></strong><small>생산 실적 ÷ 계획 수량</small></div><div class="kpi"><div class="label">평균 양품률 <span class="icon">◇</span></div><strong>${quality.toFixed(1)}<em>%</em></strong><small>생산 수량으로 가중 평균</small></div><div class="kpi"><div class="label">안전 점검 이행률 <span class="icon">✓</span></div><strong>${safety.toFixed(1)}<em>%</em></strong><small><b>${sums.checks}건 완료</b> 계획 ${sums.safetyTarget}건</small></div></div><div class="grid-main"><section class="card"><div class="card-head"><h2>일별 생산 현황</h2><span>단위: 대 · ${escapeHTML(site)}</span></div><div class="legend"><span><i></i>생산 실적</span><span><i class="gray"></i>계획</span></div><div class="chart" role="img" aria-label="일별 생산 실적과 계획 막대그래프">${daily.map(x=>`<div class="bar-group" title="${x.date}: 실적 ${x.p}대 / 계획 ${x.t}대"><div class="bar" style="height:${x.p/max*100}%"></div><div class="bar target" style="height:${x.t/max*100}%"></div><small>${x.date.slice(5).replace('-','/')}</small></div>`).join('')}</div><p class="chart-note">${dates[0]||'—'} ~ ${dates.at(-1)||'—'} · 막대에 마우스를 올리면 수치를 볼 수 있습니다.</p></section><section class="card"><div class="card-head"><h2>게시판 활동 분포</h2><span>총 ${posts.length}개 게시글</span></div>${categories.map(c=>{const n=posts.filter(p=>p.category===c).length;return `<div class="cat-row"><span>${c}</span><div><i style="width:${n/Math.max(1,posts.length)*100}%"></i></div><b>${n}</b></div>`}).join('')}<p class="chart-note">현재 열람 가능한 게시글을 기준으로 집계합니다.</p></section></div><div class="grid-main"><section class="card"><div class="card-head"><h2>최근 올라온 이야기</h2><a href="#board">전체 보기 →</a></div>${recent.map(row).join('')||'<div class="empty">첫 이야기를 나눠 주세요.</div>'}</section><section class="card"><div class="card-head"><h2>놓치지 마세요</h2><a href="#board/공지사항">공지사항 →</a></div>${notices.map(p=>`<div class="notice-feature" data-post="${p.id}" tabindex="0" role="link">${tag('공지사항')}<strong>${escapeHTML(p.title)}</strong><small>${date(p.created_at)} · ${escapeHTML(p.author_name)}</small></div>`).join('')}</section></div>`;
$('siteFilter').value=site;$('periodFilter').value=days;$('siteFilter').onchange=e=>{site=e.target.value;renderDashboard()};$('periodFilter').onchange=e=>{days=+e.target.value;renderDashboard()};$('goBoard').onclick=()=>location.hash='board';bindPostLinks();}
function renderBoard(category='전체'){const q=search.toLocaleLowerCase();let filtered=posts.filter(p=>(category==='전체'||p.category===category)&&(!q||(p.title+' '+p.body+' '+p.author_name).toLocaleLowerCase().includes(q)));const totalPages=Math.max(1,Math.ceil(filtered.length/8));page=Math.min(page,totalPages);const shown=filtered.slice((page-1)*8,page*8);$('main').innerHTML=`<div class="page-heading"><div><span class="eyebrow">COMMUNITY</span><h1>${category==='전체'?'함께 나누는 이야기':escapeHTML(category)}</h1><p>현장의 경험과 새로운 아이디어가 만나는 곳</p></div><button class="primary" data-write>＋ 새 글 작성</button></div>${sampleBanner}<div class="tabs">${['전체',...categories].map(c=>`<button data-category="${c}" class="${category===c?'active':''}">${c}</button>`).join('')}</div><div class="board-toolbar"><span class="muted">총 <b>${filtered.length}</b>개의 이야기</span><form class="search-wrap" id="searchForm"><input id="boardSearch" aria-label="게시글 검색" placeholder="제목, 내용, 작성자 검색" value="${escapeHTML(search)}"><button class="secondary">검색</button></form></div><section class="card" style="padding:0 0 15px;overflow:hidden"><table class="board-table"><thead><tr><th>게시판</th><th>제목</th><th>작성자</th><th>사업장</th><th>등록일</th></tr></thead><tbody>${shown.map(p=>`<tr data-post="${p.id}" tabindex="0" role="link"><td>${tag(p.category)}</td><td class="title-cell"><strong>${escapeHTML(p.title)} ${commentCounts[p.id]?'<span style="color:#e87744">['+commentCounts[p.id]+']</span>':''}</strong><small>${p.is_sample?'교육용 샘플 · ':''}${escapeHTML(p.body.replace(/\n/g,' ').slice(0,50))}…</small></td><td>${escapeHTML(p.author_name)}</td><td>${escapeHTML(p.department)}</td><td>${date(p.created_at)}</td></tr>`).join('')}</tbody></table>${!shown.length?'<div class="empty">검색 결과가 없습니다. 다른 검색어를 입력해 보세요.</div>':''}</section><div class="board-bottom"><span>${page} / ${totalPages} 페이지</span><div class="pagination">${Array.from({length:totalPages},(_,i)=>`<button data-number="${i+1}" class="${page===i+1?'active':''}">${i+1}</button>`).join('')}</div></div>${!user?'<div class="member-note">샘플 글을 둘러보셨나요? 회원가입 후 직접 글을 쓰고 댓글로 소통해 보세요.</div>':''}`;
$('searchForm').onsubmit=e=>{e.preventDefault();search=$('boardSearch').value.trim();page=1;renderBoard(category)};document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{page=1;location.hash=b.dataset.category==='전체'?'board':'board/'+b.dataset.category;renderBoard(b.dataset.category)});document.querySelectorAll('[data-number]').forEach(b=>b.onclick=()=>{page=+b.dataset.number;renderBoard(category);scrollTo(0,0)});bindPostLinks();}
function linkedBody(body){return escapeHTML(body).replace(/https:\/\/[^\s<]+/g,s=>`<a href="${s}" target="_blank" rel="noopener noreferrer">${s}</a>`)}
async function renderPost(id,ticket){const p=posts.find(x=>x.id===id);if(!p){$('main').innerHTML='<div class="card empty">글을 찾을 수 없습니다. <a href="#board">게시판으로 돌아가기 →</a></div>';return}activePost=p;const {data:comments,error}=await db.from('hub_comments').select('*').eq('post_id',id).order('created_at');if(ticket!==routeTicket)return;if(error)throw error;const mine=user&&p.author_id===user.id&&!p.is_sample;$('main').innerHTML=`<div class="detail"><a class="muted" href="#board">← 전체 게시판</a><article class="card" style="margin-top:20px;padding:30px">${tag(p.category)} ${p.is_sample?'<span class="tag sample">교육용 샘플</span>':''}<h1>${escapeHTML(p.title)}</h1><div class="detail-meta"><strong>${escapeHTML(p.author_name)}</strong><span>${escapeHTML(p.department)}</span><time>${fullDate(p.created_at)}</time></div><div class="post-content">${linkedBody(p.body)}</div>${mine?'<div class="post-actions"><button class="secondary" id="editPost">수정</button><button class="secondary" id="deletePost">삭제</button></div>':''}<section class="comments"><h2>댓글 <span style="color:#e87542">${comments.length}</span></h2>${comments.map(c=>`<div class="comment"><header><strong>${escapeHTML(c.author_name)}</strong>${c.is_sample?'<span class="tag sample">샘플</span>':''}<time>${fullDate(c.created_at)}</time>${user&&c.author_id===user.id?`<button class="link-btn" data-delete-comment="${c.id}">삭제</button>`:''}</header><p>${escapeHTML(c.body)}</p></div>`).join('')||'<p class="muted">첫 댓글을 남겨 보세요.</p>'}${user?'<form class="comment-form" id="commentForm"><textarea id="commentBody" required maxlength="2000" rows="3" aria-label="댓글 내용" placeholder="업무에 도움이 되는 의견을 남겨 주세요."></textarea><button class="primary" id="commentSubmit">댓글 등록</button></form><p class="error" id="commentError" role="alert"></p>':'<div class="member-note">로그인하면 댓글을 남길 수 있습니다. <button class="link-btn" id="commentLogin">로그인 →</button></div>'}</section></article></div>`;
if(mine){$('editPost').onclick=()=>openWrite(p);$('deletePost').onclick=()=>$('deleteDialog').showModal()}if(user){$('commentForm').onsubmit=async e=>{e.preventDefault();$('commentSubmit').disabled=true;try{const body=$('commentBody').value.trim();if(!body)throw Error('댓글 내용을 입력해 주세요.');const {error}=await db.from('hub_comments').insert({post_id:id,body,author_id:user.id});if(error)throw error;await loadData();await renderRoute();toast('댓글을 등록했습니다.')}catch(e){$('commentError').textContent=errorMessage(e);$('commentSubmit').disabled=false}};}else $('commentLogin').onclick=()=>openAuth('login');document.querySelectorAll('[data-delete-comment]').forEach(b=>b.onclick=async()=>{b.disabled=true;const {error}=await db.from('hub_comments').delete().eq('id',b.dataset.deleteComment);if(error){toast(errorMessage(error));b.disabled=false}else{await loadData();await renderRoute();toast('댓글을 삭제했습니다.')}});}
async function renderRoute(){const ticket=++routeTicket;let route;try{route=decodeURIComponent(location.hash.slice(1)||'dashboard')}catch{route='dashboard'}const [base,...rest]=route.split('/');const section=base==='dashboard'?'dashboard':'board';$('breadcrumb').textContent=section==='dashboard'?'대시보드':'게시판';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+route||(a.dataset.page===section&&!rest.length)));if(base==='post')await renderPost(rest[0],ticket);else if(base==='board')renderBoard(categories.includes(rest.join('/'))?rest.join('/'):'전체');else renderDashboard();}
window.addEventListener('hashchange',()=>{page=1;renderRoute().catch(e=>toast(errorMessage(e)));scrollTo(0,0)});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!loading)refresh()});$('today').textContent=new Date().toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'});
(async()=>{try{const {data,error}=await db.auth.getSession();if(error)throw error;user=data.session?.user||null;if(user)await ensureProfile();await refresh();}catch(e){$('main').innerHTML='<div class="error-card">'+escapeHTML(errorMessage(e))+'</div>'}})();
db.auth.onAuthStateChange((event,session)=>{if(event==='SIGNED_OUT'){user=null;profile=null;updateAuth()}else if(event==='TOKEN_REFRESHED')user=session?.user||null;});
